CREATE OR REPLACE FUNCTION public.trg_lock_and_validate_tournament_live_seat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_ids uuid[];
  v_is_live_acquisition boolean := false;
  v_proof_open boolean := false;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.table_id IS NOT DISTINCT FROM OLD.table_id
     AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
     AND NEW.seat_number IS NOT DISTINCT FROM OLD.seat_number
     AND NEW.stack IS NOT DISTINCT FROM OLD.stack
     AND NEW.left_at IS NOT DISTINCT FROM OLD.left_at THEN
    RETURN NEW;
  END IF;

  IF TG_OP <> 'INSERT' THEN
    SELECT t.tournament_id INTO v_old_tournament_id
      FROM public.tables t
     WHERE t.id = OLD.table_id;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.table_id IS NOT DISTINCT FROM OLD.table_id THEN
    -- Same table on both sides: one lookup answers for both (2026-09-10).
    v_new_tournament_id := v_old_tournament_id;
  ELSIF TG_OP <> 'DELETE' THEN
    SELECT t.tournament_id INTO v_new_tournament_id
      FROM public.tables t
     WHERE t.id = NEW.table_id;
  END IF;

  -- A CASH SEAT HAS NO LAUNCH PROOF TO LOCK (2026-09-10). With both ids NULL
  -- the body below cannot lock, refuse or require anything: v_ids would be
  -- {NULL,NULL}, the proof-open test is false, the lock helper returns on an
  -- empty set, and the roster check needs a tournament. Measured 6.4 ms per
  -- seat write on a cash table for that no-op; see the migration header.
  IF v_old_tournament_id IS NULL AND v_new_tournament_id IS NULL THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  v_ids := CASE
    WHEN TG_OP = 'INSERT' THEN ARRAY[v_new_tournament_id]
    WHEN TG_OP = 'DELETE' THEN ARRAY[v_old_tournament_id]
    ELSE ARRAY[v_old_tournament_id, v_new_tournament_id]
  END;

  IF TG_OP = 'INSERT' THEN
    v_is_live_acquisition := NEW.left_at IS NULL AND NEW.user_id IS NOT NULL;
  ELSIF TG_OP = 'UPDATE' THEN
    v_is_live_acquisition := NEW.left_at IS NULL
      AND NEW.user_id IS NOT NULL
      AND (
        OLD.left_at IS NOT NULL
        OR OLD.user_id IS DISTINCT FROM NEW.user_id
        OR OLD.table_id IS DISTINCT FROM NEW.table_id
      );
  END IF;

  IF NOT v_is_live_acquisition THEN
    -- THE SAME ROWS AS `t.id = ANY(v_ids)`, WITHOUT A RE-PLAN PER CALL
    -- (2026-09-10). v_ids is {new} / {old} / {old,new} for INSERT / DELETE /
    -- UPDATE, and the side that is not assigned is NULL, which matches nothing
    -- in either form. With an array parameter PL/pgSQL keeps a custom plan and
    -- re-plans this statement on every seat write (0.83-0.99 ms measured);
    -- with two scalar parameters it adopts the generic plan (0.026 ms).
    SELECT EXISTS (
      SELECT 1
        FROM public.tournaments t
        LEFT JOIN public.tournament_launch_receipts r
          ON r.tournament_id = t.id
       WHERE (t.id = v_old_tournament_id OR t.id = v_new_tournament_id)
         AND (upper(t.status::text) = 'REGISTERING' OR r.completed_at IS NULL)
         AND (upper(t.status::text) = 'REGISTERING' OR r.tournament_id IS NOT NULL)
    ) INTO v_proof_open;
    IF NOT v_proof_open THEN
      RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
    END IF;
  END IF;

  PERFORM *
    FROM public.fn_lock_tournament_launch_proof_parents(v_ids);

  IF TG_OP <> 'DELETE'
     AND NEW.left_at IS NULL
     AND NEW.user_id IS NOT NULL
     AND v_new_tournament_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
         FROM public.tournament_players p
        WHERE p.tournament_id = v_new_tournament_id
          AND p.user_id = NEW.user_id
          AND p.status IN ('registered', 'playing')
     ) THEN
    RAISE EXCEPTION
      'TOURNAMENT_SEAT_ROSTER_REQUIRED: live seat user % has no active roster in tournament %',
      NEW.user_id, v_new_tournament_id
      USING ERRCODE = '23514';
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_move_tournament_player(p_tournament_id uuid, p_user_id uuid, p_source_table_id uuid, p_destination_table_id uuid, p_destination_seat_number integer, p_request_id uuid, p_source_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_tp public.tournament_players%ROWTYPE;
  v_source public.table_seats%ROWTYPE;
  v_destination public.table_seats%ROWTYPE;
  v_destination_id uuid;
  v_token uuid;
  v_moved_at timestamptz;
  v_rows integer;
  v_live_count integer;
  v_result jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'fn_move_tournament_player requires service authority'
      USING ERRCODE='28000';
  END IF;
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_source_table_id IS NULL OR p_destination_table_id IS NULL
     OR p_request_id IS NULL OR p_source_table_id=p_destination_table_id
     OR p_source_mode NOT IN ('live_source','closed_orphan')
     OR p_destination_seat_number NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'invalid tournament move identity' USING ERRCODE='22023';
  END IF;

  IF current_setting('app.smarter_data_actor',true)='tournament-manager' THEN
    PERFORM smarter_private.f06_authority(p_tournament_id,NULLIF(current_setting('app.smarter_tournament_lease_generation',true),'')::uuid);
  END IF;
  -- HOTFIX EDIT (b): G -> T via the 20260910035245 helper, not the raw global key.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM pg_advisory_xact_lock(
    hashtextextended('table_cap:'||p_user_id::text,0));

  v_result:=public.fn_ca_tournament_seat_move_receipt(p_request_id);
  IF v_result IS NOT NULL THEN
    IF (v_result->>'tournament_id')::uuid IS DISTINCT FROM p_tournament_id
       OR (v_result->>'user_id')::uuid IS DISTINCT FROM p_user_id
       OR (v_result->>'source_table_id')::uuid IS DISTINCT FROM p_source_table_id
       OR (v_result->>'destination_table_id')::uuid
            IS DISTINCT FROM p_destination_table_id
       OR v_result->>'source_mode' IS DISTINCT FROM p_source_mode
       OR (v_result->>'destination_seat_number')::integer
            IS DISTINCT FROM p_destination_seat_number THEN
      RAISE EXCEPTION 'tournament move request id belongs to another operation'
        USING ERRCODE='23505';
    END IF;
    RETURN v_result||jsonb_build_object('replayed',true);
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist',p_tournament_id
      USING ERRCODE='P0002';
  END IF;
  IF upper(COALESCE(v_t.status,''))<>'RUNNING' THEN
    RAISE EXCEPTION 'tournament % is not RUNNING',p_tournament_id
      USING ERRCODE='55000';
  END IF;

  SELECT * INTO v_tp FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND OR v_tp.status<>'playing'
     OR v_tp.table_id IS DISTINCT FROM p_source_table_id THEN
    RAISE EXCEPTION 'tournament move source roster is not exact'
      USING ERRCODE='P0404';
  END IF;

  PERFORM tb.id FROM public.tables tb
   WHERE tb.id IN (p_source_table_id,p_destination_table_id)
   ORDER BY tb.id FOR UPDATE;
  IF (SELECT count(*) FROM public.tables tb
       WHERE tb.id IN (p_source_table_id,p_destination_table_id)
         AND tb.tournament_id=p_tournament_id)<>2 THEN
    RAISE EXCEPTION 'tournament move tables do not share the event'
      USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tables tb
     WHERE tb.id=p_destination_table_id
       AND (COALESCE(tb.is_deleted,false)
         OR lower(COALESCE(tb.status,''))='closed'
         OR p_destination_seat_number>COALESCE(tb.max_players,9))) THEN
    RAISE EXCEPTION 'tournament move destination is not open'
      USING ERRCODE='55000';
  END IF;
  IF p_source_mode='closed_orphan' AND NOT EXISTS (
    SELECT 1 FROM public.tables tb
     WHERE tb.id=p_source_table_id
       AND (COALESCE(tb.is_deleted,false)
         OR lower(COALESCE(tb.status,''))='closed')) THEN
    RAISE EXCEPTION 'closed-orphan move source is not closed'
      USING ERRCODE='55000';
  END IF;
  IF p_source_mode='live_source' AND EXISTS (
    SELECT 1 FROM public.tables tb
     WHERE tb.id=p_source_table_id
       AND (COALESCE(tb.is_deleted,false)
         OR lower(COALESCE(tb.status,''))='closed')) THEN
    RAISE EXCEPTION 'live-source move source is closed'
      USING ERRCODE='55000';
  END IF;

  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
     AND s.left_at IS NULL
   ORDER BY s.id FOR UPDATE OF s;
  SELECT count(*) INTO v_live_count
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
     AND s.left_at IS NULL;
  IF v_live_count<>1 THEN
    RAISE EXCEPTION 'tournament move requires exactly one live source seat'
      USING ERRCODE='P0404';
  END IF;

  SELECT s.* INTO v_source FROM public.table_seats s
   WHERE s.table_id=p_source_table_id AND s.user_id=p_user_id
     AND s.left_at IS NULL FOR UPDATE;
  IF NOT FOUND OR v_source.seat_number IS DISTINCT FROM v_tp.seat_number
     OR v_source.stack IS NULL
     OR v_source.stack::text IN ('NaN','Infinity','-Infinity')
     OR v_source.stack<=0
     OR abs(v_source.stack-v_tp.chips::numeric)>0.5 THEN
    RAISE EXCEPTION 'tournament move source chips or coordinates are not exact'
      USING ERRCODE='P0404';
  END IF;

  SELECT s.* INTO v_destination FROM public.table_seats s
   WHERE s.table_id=p_destination_table_id
     AND s.seat_number=p_destination_seat_number FOR UPDATE;
  IF FOUND AND v_destination.left_at IS NULL THEN
    RAISE EXCEPTION 'tournament move destination seat is occupied'
      USING ERRCODE='23505';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id
       AND tp.user_id<>p_user_id
       AND tp.status IN ('registered','playing')
       AND tp.table_id=p_destination_table_id
       AND tp.seat_number=p_destination_seat_number) THEN
    RAISE EXCEPTION 'tournament move destination roster is occupied'
      USING ERRCODE='23505';
  END IF;

  PERFORM smarter_private.f06_move_guard(p_tournament_id,p_user_id,p_source_table_id,p_destination_table_id,p_destination_seat_number,p_request_id,p_source_mode,v_source.id,v_source.occupancy_id);
  v_token:=public.fn_ca_open_tournament_seat_exit_authority(
    p_tournament_id,'move',p_user_id);
  v_moved_at:=clock_timestamp();
  BEGIN
    UPDATE public.table_seats s
       SET stack=0,left_at=v_moved_at,status='left',leave_pending=false,
           is_sitting_out=false,is_away=false,sit_out_at=NULL,
           scheduled_leave_hands=NULL
     WHERE s.id=v_source.id AND s.left_at IS NULL
       AND s.stack=v_source.stack;
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN
      RAISE EXCEPTION 'tournament move lost its locked source seat'
        USING ERRCODE='55000';
    END IF;

    IF v_destination.id IS NULL THEN
      INSERT INTO public.table_seats(
        table_id,seat_number,user_id,player_id,member_id,stack,
        is_sitting_out,is_away,joined_at,horse_id,scheduled_leave_hands,
        left_at,status,leave_pending,auto_rebuy,time_bank_remaining,
        time_bank_uses_remaining,sit_out_at,entry_hold,entry_post_agreed)
      VALUES(
        p_destination_table_id,p_destination_seat_number,p_user_id,
        v_source.player_id,v_source.member_id,v_source.stack,
        coalesce(v_source.is_sitting_out,false),coalesce(v_source.is_away,false),
        v_moved_at,v_source.horse_id,NULL,NULL,'active',false,
        v_source.auto_rebuy,v_source.time_bank_remaining,
        v_source.time_bank_uses_remaining,v_source.sit_out_at,NULL,
        v_source.entry_post_agreed)
      RETURNING id INTO v_destination_id;
    ELSE
      UPDATE public.table_seats s
         SET user_id=p_user_id,player_id=v_source.player_id,
             member_id=v_source.member_id,stack=v_source.stack,
             is_sitting_out=coalesce(v_source.is_sitting_out,false),
             is_away=coalesce(v_source.is_away,false),joined_at=v_moved_at,
             horse_id=v_source.horse_id,scheduled_leave_hands=NULL,
             left_at=NULL,status='active',leave_pending=false,
             auto_rebuy=v_source.auto_rebuy,
             time_bank_remaining=v_source.time_bank_remaining,
             time_bank_uses_remaining=v_source.time_bank_uses_remaining,
             sit_out_at=v_source.sit_out_at,entry_hold=NULL,
             entry_post_agreed=v_source.entry_post_agreed
       WHERE s.id=v_destination.id AND s.left_at IS NOT NULL
       RETURNING id INTO v_destination_id;
      IF v_destination_id IS NULL THEN
        RAISE EXCEPTION 'tournament move could not reuse destination seat'
          USING ERRCODE='55000';
      END IF;
    END IF;

    UPDATE public.tournament_players tp
       SET table_id=p_destination_table_id,
           seat_number=p_destination_seat_number
     WHERE tp.id=v_tp.id AND tp.status='playing'
       AND tp.table_id=p_source_table_id
       AND tp.seat_number=v_source.seat_number;
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN
      RAISE EXCEPTION 'tournament move lost its locked roster row'
        USING ERRCODE='55000';
    END IF;

    UPDATE public.tables tb
       SET current_players=(
         SELECT count(*) FROM public.table_seats s
          WHERE s.table_id=tb.id AND s.left_at IS NULL),
           updated_at=now()
     WHERE tb.id IN (p_source_table_id,p_destination_table_id);

    IF (SELECT count(*) FROM public.table_seats s
        JOIN public.tables tb ON tb.id=s.table_id
       WHERE tb.tournament_id=p_tournament_id
         AND s.user_id=p_user_id AND s.left_at IS NULL)<>1
       OR NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.id=v_destination_id
            AND s.table_id=p_destination_table_id
            AND s.seat_number=p_destination_seat_number
            AND s.user_id=p_user_id AND s.left_at IS NULL
            AND s.stack=v_source.stack)
       OR NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.id=v_source.id AND s.left_at=v_moved_at AND s.stack=0)
       OR NOT EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.id=v_tp.id AND tp.status='playing'
            AND tp.table_id=p_destination_table_id
            AND tp.seat_number=p_destination_seat_number) THEN
      RAISE EXCEPTION 'tournament move final proof is not exact'
        USING ERRCODE='P0404';
    END IF;

    INSERT INTO public.tournament_seat_move_receipts(
      request_id,tournament_id,user_id,source_table_id,destination_table_id,
      source_seat_id,destination_seat_id,source_seat_number,
      destination_seat_number,source_mode,stack,moved_at)
    VALUES(
      p_request_id,p_tournament_id,p_user_id,p_source_table_id,
      p_destination_table_id,v_source.id,v_destination_id,
      v_source.seat_number,p_destination_seat_number,p_source_mode,
      v_source.stack,v_moved_at);

    -- HOTFIX EDIT (a): the consuming guard trigger is not installed; rows are deleted, not counted.
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
    RAISE;
  END;

  v_result:=public.fn_ca_tournament_seat_move_receipt(p_request_id);
  IF v_result IS NULL THEN
    RAISE EXCEPTION 'tournament move receipt did not persist'
      USING ERRCODE='P0404';
  END IF;
  RETURN v_result||jsonb_build_object('replayed',false);
END;
$function$

CREATE OR REPLACE FUNCTION smarter_private.f06_lock_break(t uuid, g uuid, b uuid, extra uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE users uuid[];ids uuid[];
BEGIN
 PERFORM smarter_private.f06_authority(t,g);
 PERFORM public.fn_ca_lock_settlement_lane_for_tournament(t);
 -- Read active destinations only AFTER acquiring the lane, then physical rows.
 SELECT array_agg(user_id ORDER BY user_id) INTO users FROM smarter_private.f06_members WHERE break_id=b;
 SELECT array_agg(DISTINCT x) INTO ids FROM (
 SELECT source_table_id x FROM smarter_private.f06_operations WHERE break_id=b AND tournament_id=t
 UNION SELECT destination_table_id FROM smarter_private.f06_attempts WHERE break_id=b UNION SELECT extra) q;
 PERFORM smarter_private.f06_prefix(t,g,COALESCE(users,'{}'),ids);
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE break_id=b AND tournament_id=t) THEN
 RAISE EXCEPTION 'F06_UNKNOWN_BREAK' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM smarter_private.f06_operations WHERE break_id=b FOR UPDATE;
END $function$

CREATE OR REPLACE FUNCTION public.fn_f06_begin_break(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid, p_members jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE o smarter_private.f06_operations; x record; norm jsonb; users uuid[];ids uuid[];
BEGIN
 IF jsonb_typeof(p_members) IS DISTINCT FROM 'array' OR jsonb_array_length(p_members) NOT BETWEEN 1 AND 10 THEN
 RAISE EXCEPTION 'F06_INVALID_MANIFEST' USING ERRCODE='22023'; END IF;
 SELECT jsonb_agg(value ORDER BY value->>'user_id') INTO norm FROM jsonb_array_elements(p_members);
 SELECT array_agg((value->>'user_id')::uuid),array_agg((value->>'destination_table_id')::uuid) INTO users,ids FROM jsonb_array_elements(norm);
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id AND tournament_id=p_tournament_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'F06_UNKNOWN_BREAK' USING ERRCODE='22023'; END IF;
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,users,array_append(ids,o.source_table_id));
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id FOR UPDATE;
 IF o.manifest IS NOT NULL THEN
 IF o.manifest IS DISTINCT FROM norm THEN RAISE EXCEPTION 'F06_CHANGED_MANIFEST' USING ERRCODE='22023'; END IF;
 RETURN smarter_private.f06_state(p_break_id); END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE table_id=o.source_table_id AND state='reserved') THEN
 RETURN jsonb_build_object('ok',false,'reason','park_not_drained'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tournaments WHERE id=p_tournament_id AND upper(status)='RUNNING') THEN
 RETURN jsonb_build_object('ok',false,'reason','terminal_handoff_required'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tables WHERE id=o.source_table_id AND f06_lifecycle=o.lifecycle AND lower(status)<>'closed' AND NOT COALESCE(is_deleted,false)) THEN
 RAISE EXCEPTION 'F06_SOURCE_LIFECYCLE' USING ERRCODE='55000'; END IF;
 IF (SELECT count(*) FROM public.table_seats WHERE table_id=o.source_table_id AND left_at IS NULL)<>jsonb_array_length(norm)
 OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id AND table_id=o.source_table_id AND status IN ('playing','registered'))<>jsonb_array_length(norm)
 OR (SELECT count(DISTINCT member_user) FROM unnest(users) member_user)<>jsonb_array_length(norm) THEN
 RAISE EXCEPTION 'F06_WHOLE_ROSTER_REQUIRED' USING ERRCODE='22023'; END IF;
 FOR x IN SELECT * FROM jsonb_to_recordset(norm) AS m(user_id uuid,source_seat_id uuid,source_seat_number integer,occupancy_id uuid,request_id uuid,destination_table_id uuid,destination_seat_number integer) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.table_seats s JOIN public.tournament_players p ON p.user_id=s.user_id AND p.table_id=s.table_id AND p.seat_number=s.seat_number
 WHERE s.id=x.source_seat_id AND s.table_id=o.source_table_id AND s.user_id=x.user_id AND s.seat_number=x.source_seat_number AND s.occupancy_id=x.occupancy_id
 AND s.left_at IS NULL AND s.stack>0 AND s.stack::text NOT IN ('NaN','Infinity','-Infinity') AND p.tournament_id=p_tournament_id AND p.status='playing' AND abs(s.stack-p.chips::numeric)<=0.5)
 OR EXISTS(SELECT 1 FROM public.tournament_seat_move_receipts WHERE request_id=x.request_id) THEN RAISE EXCEPTION 'F06_SOURCE_NOT_EXACT' USING ERRCODE='55000'; END IF;
 PERFORM smarter_private.f06_validate_destination(p_tournament_id,o.source_table_id,x.destination_table_id,x.destination_seat_number);
 INSERT INTO smarter_private.f06_members VALUES(p_break_id,x.user_id,x.source_seat_id,x.source_seat_number,x.occupancy_id);
 INSERT INTO smarter_private.f06_attempts(request_id,break_id,user_id,revision,destination_table_id,destination_seat_number,generation)
 VALUES(x.request_id,p_break_id,x.user_id,1,x.destination_table_id,x.destination_seat_number,p_lease_generation);
 END LOOP;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_attempts WHERE break_id=p_break_id GROUP BY destination_table_id,destination_seat_number HAVING count(*)>1) THEN
 RAISE EXCEPTION 'F06_DUPLICATE_DESTINATION' USING ERRCODE='22023'; END IF;
 UPDATE smarter_private.f06_operations SET manifest=norm,state='begun' WHERE break_id=p_break_id;
 RETURN smarter_private.f06_state(p_break_id);
END $function$

CREATE OR REPLACE FUNCTION public.fn_f06_request_park(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid, p_table_id uuid, p_lifecycle bigint, p_boundary_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE o smarter_private.f06_operations;
BEGIN
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,'{}',ARRAY[p_table_id]);
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id;
 IF FOUND THEN
 IF (o.tournament_id,o.source_table_id,o.lifecycle,o.boundary_id) IS DISTINCT FROM (p_tournament_id,p_table_id,p_lifecycle,p_boundary_id) THEN
 RAISE EXCEPTION 'F06_CHANGED_PARK_REPLAY' USING ERRCODE='22023'; END IF;
 RETURN smarter_private.f06_state(p_break_id); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tournaments WHERE id=p_tournament_id AND upper(status)='RUNNING') THEN
 RETURN jsonb_build_object('ok',false,'reason','tournament_not_running'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tables WHERE id=p_table_id AND tournament_id=p_tournament_id AND f06_lifecycle=p_lifecycle
 AND NOT COALESCE(is_deleted,false) AND lower(status)<>'closed') THEN RAISE EXCEPTION 'F06_SOURCE_LIFECYCLE' USING ERRCODE='55000'; END IF;
 INSERT INTO smarter_private.f06_operations(break_id,tournament_id,source_table_id,lifecycle,boundary_id,origin_generation)
 VALUES(p_break_id,p_tournament_id,p_table_id,p_lifecycle,p_boundary_id,p_lease_generation);
 RETURN smarter_private.f06_state(p_break_id);
END $function$

CREATE OR REPLACE FUNCTION public.fn_f06_discover_breaks(p_tournament_id uuid, p_lease_generation uuid, p_expected_cursor_revision bigint, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE c smarter_private.f06_cursors;items jsonb;last_id bigint;wrapped boolean:=false;
BEGIN
 IF p_limit NOT BETWEEN 1 AND 32 OR p_limit IS NULL THEN RAISE EXCEPTION 'F06_PAGE_SIZE' USING ERRCODE='22023'; END IF;
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,'{}','{}');
 INSERT INTO smarter_private.f06_cursors(tournament_id) VALUES(p_tournament_id) ON CONFLICT DO NOTHING;
 SELECT * INTO c FROM smarter_private.f06_cursors WHERE tournament_id=p_tournament_id FOR UPDATE;
 IF c.revision IS DISTINCT FROM p_expected_cursor_revision THEN RETURN jsonb_build_object('ok',false,'reason','cursor_revision_conflict','cursor_revision',c.revision::text,'wrapped',false,'operations','[]'::jsonb); END IF;
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE tournament_id=p_tournament_id AND state NOT IN ('acknowledged','withdrawn_before_manifest') AND ordinal>c.ordinal) THEN c.ordinal:=0;wrapped:=true; END IF;
 SELECT jsonb_agg(smarter_private.f06_state(q.break_id) ORDER BY q.ordinal),max(q.ordinal) INTO items,last_id FROM
 (SELECT break_id,ordinal FROM smarter_private.f06_operations WHERE tournament_id=p_tournament_id AND state NOT IN ('acknowledged','withdrawn_before_manifest') AND ordinal>c.ordinal ORDER BY ordinal LIMIT p_limit) q;
 UPDATE smarter_private.f06_cursors SET ordinal=COALESCE(last_id,0),revision=revision+1 WHERE tournament_id=p_tournament_id;
 RETURN jsonb_build_object('ok',true,'reason',NULL,'cursor_revision',(c.revision+1)::text,'wrapped',wrapped,'operations',COALESCE(items,'[]'::jsonb));
END $function$

CREATE OR REPLACE FUNCTION public.fn_close_tournament_entry_window(p_tournament_id uuid, p_source text DEFAULT 'engine.entry_window_close'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_deadline timestamptz;
  v_retry_ms bigint;
  v_mode text;
BEGIN
  /* THE LANE BEFORE THE ROW (2026-10-25). G shared, then T(id) exclusive,
     then the tournaments row: the order of every other writer of this
     event. Finalizing the pool here fires the deferred payer, which asks
     for T(id) exclusive at COMMIT; holding the row without the lane made
     that a deadlock with any rebuy, add-on or hand that holds T(id) and
     waits for the row. Taken first, the payer's request is re-entrant. */
  IF p_tournament_id IS NOT NULL THEN
    PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  END IF;
  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','not_found'); END IF;
  IF v_t.status<>'RUNNING' THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_not_running','status',v_t.status);
  END IF;

  -- The admission predicate already owns the earliest level/clock cutoff.
  -- Report a clock-bounded hybrid as minutes so the serving engine arms its
  -- existing database-relative deadline timer as well as its level events.
  v_mode := CASE WHEN COALESCE(v_t.late_reg_mins,0)>0 THEN 'minutes'
    WHEN COALESCE(v_t.late_reg_levels,v_t.rebuy_levels,0)>0 THEN 'levels'
    ELSE 'immediate' END;
  IF v_mode='minutes' AND v_t.started_at IS NULL
     AND NOT COALESCE(v_t.prize_pool_finalized,false) THEN
    RETURN jsonb_build_object('ok',false,
      'reason','started_at_required_for_minutes_window','window_mode',v_mode);
  END IF;
  -- Owner 2026-10-31: elapsed minutes and a full field cannot start add-ons
  -- before the last configured late-entry level has completed. Admission
  -- retains its existing clock/cap rules; this is the add-on/pool transition.
  IF COALESCE(v_t.add_on_available,false)
     AND NOT COALESCE(v_t.prize_pool_finalized,false)
     AND COALESCE(v_t.late_reg_levels,v_t.rebuy_levels,0)>0
     AND (v_t.current_level IS NULL OR
          v_t.current_level<COALESCE(v_t.late_reg_levels,v_t.rebuy_levels,0)) THEN
    RETURN jsonb_build_object('ok',true,'entry_closed',false,
      'window_mode','levels','retry_after_ms',NULL,
      'reason','addon_waiting_for_late_entry_levels');
  END IF;
  IF (NOT COALESCE(v_t.add_on_available,false)
          AND public.fn_tournament_late_registration_open(p_tournament_id))
     OR (COALESCE(v_t.add_on_available,false)
         AND NOT COALESCE(v_t.prize_pool_finalized,false)
         AND COALESCE(v_t.late_reg_levels,v_t.rebuy_levels,0)<=0
         AND COALESCE(v_t.late_reg_mins,0)>0
         AND clock_timestamp()<v_t.started_at+make_interval(mins=>v_t.late_reg_mins)) THEN
    IF v_mode='minutes' THEN
      v_deadline:=v_t.started_at+make_interval(mins=>v_t.late_reg_mins);
      v_retry_ms:=GREATEST(
        ceil(extract(epoch FROM (v_deadline-clock_timestamp()))*1000),0)::bigint;
    END IF;
    RETURN jsonb_build_object('ok',true,'entry_closed',false,
      'window_mode',v_mode,'retry_after_ms',v_retry_ms);
  END IF;

  -- Add-on chips can still change the final pool. Close entry now, but let the
  -- persisted add-on deadline own finalization and its receipt.
  IF COALESCE(v_t.add_on_available,false)
     AND NOT COALESCE(v_t.prize_pool_finalized,false) THEN
    RETURN jsonb_build_object(
      'ok',true,'entry_closed',true,'window_mode',v_mode,
      'finalized',false,'finalization_deferred',true,
      'reason','addon_required','retry_after_ms',NULL);
  END IF;

  /* NO OVERLAY CHIPS BEFORE THE REBUY WINDOW CLOSES (Dan, 2026-11-14: "NO
     CHIPS ARE EVER EVER EVER SUPPOSED TO GO TO ANY TOURNAMENT 'FOR OVERLAYS'
     UNTIL THE REGISTRATION / REBUY / ADD ON PERIOD HAS OFFICALLY ENDED").
     Finalizing funds the guarantee, and it also ends rebuys
     (fn_ca_tournament_rebuy_window answers closed once the pool is final). An
     event whose rebuy levels outlast its late-registration levels (the 25 Chip
     Bankroll Builder and Sunday 200 Deep Stack: 9 late-registration levels,
     12 rebuy levels, no add-on) was finalized at level 9: the guarantee was
     funded while three configured rebuy levels were still ahead, and those
     rebuys were refused. Registration still closes at its own level; the pool
     stays open and unfunded until the rebuy window closes. The engine asks
     again at every blind transition (levels), or at the clock deadline. */
  IF NOT COALESCE(v_t.prize_pool_finalized,false)
     AND COALESCE((public.fn_ca_tournament_rebuy_window(p_tournament_id)->>'open')::boolean,false) THEN
    IF COALESCE(v_t.late_reg_mins,0)>0 AND v_t.started_at IS NOT NULL THEN
      v_deadline:=v_t.started_at+make_interval(mins=>v_t.late_reg_mins);
      v_retry_ms:=GREATEST(
        ceil(extract(epoch FROM (v_deadline-clock_timestamp()))*1000),0)::bigint;
      RETURN jsonb_build_object('ok',true,'entry_closed',false,
        'window_mode','minutes','retry_after_ms',v_retry_ms,'reason','rebuy_window_open');
    END IF;
    RETURN jsonb_build_object('ok',true,'entry_closed',false,
      'window_mode','levels','retry_after_ms',NULL,'reason','rebuy_window_open');
  END IF;

  RETURN public.fn_finalize_tournament_entry_pool_locked(
    p_tournament_id,p_source,v_mode);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sweep_pending_tournament_bounties(p_tournament_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  o public.tournament_bounty_obligations%ROWTYPE;
  candidate record;
  v_result jsonb;
  v_reserved jsonb;
  v_award_id uuid;
  v_processed integer := 0;
  v_settled integer := 0;
  v_failed integer := 0;
  v_settled_tournament_ids uuid[] := ARRAY[]::uuid[];
  v_recipients jsonb;
  v_op_hex text;
  v_op_id uuid;
  v_limit integer := GREATEST(1,LEAST(COALESCE(p_limit,20),100));
  v_scope uuid := p_tournament_id;
BEGIN
  -- Admission must not queue behind a busy event while holding the global
  -- shared lane. Try the same G -> T lock order as the rolling authority.
  -- Failed transaction try-locks acquire nothing; success holds the same locks
  -- through commit. Only one tournament lane can be acquired by this call.
  v_scope := NULL;
  IF pg_try_advisory_xact_lock_shared(
       hashtextextended('ca:tournament-terminal-settlement:v1', 0)) THEN
    FOR candidate IN
      SELECT bo.tournament_id, min(bo.next_attempt_at) AS due_at
        FROM public.tournament_bounty_obligations bo
       WHERE bo.state='pending' AND bo.next_attempt_at<=now()
         AND (p_tournament_id IS NULL OR bo.tournament_id=p_tournament_id)
         AND NOT EXISTS (
           SELECT 1 FROM public.tournament_bounty_obligations prior
            WHERE prior.tournament_id=bo.tournament_id AND prior.state='pending'
              AND prior.mode='pko'
              AND (prior.hand_number<bo.hand_number
                   OR (prior.hand_number=bo.hand_number
                       AND prior.eliminated_user_id::text<bo.eliminated_user_id::text))
         )
       GROUP BY bo.tournament_id
       ORDER BY due_at, bo.tournament_id
    LOOP
      IF pg_try_advisory_xact_lock(hashtextextended(
           'ca:tournament-terminal-settlement:v1:' || candidate.tournament_id::text, 0)) THEN
        v_scope := candidate.tournament_id;
        EXIT;
      END IF;
    END LOOP;
  END IF;
  FOR candidate IN
    SELECT bo.id, bo.tournament_id FROM public.tournament_bounty_obligations bo
     WHERE bo.state = 'pending'
       AND bo.next_attempt_at <= now()
       AND bo.tournament_id = v_scope
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_obligations prior
          WHERE prior.tournament_id=bo.tournament_id AND prior.state='pending'
            AND prior.mode='pko'
            AND (prior.hand_number < bo.hand_number
                 OR (prior.hand_number=bo.hand_number
                     AND prior.eliminated_user_id::text < bo.eliminated_user_id::text))
       )
     ORDER BY bo.next_attempt_at, bo.tournament_id, bo.hand_number,
              bo.eliminated_user_id
     LIMIT v_limit
  LOOP
    BEGIN
      -- One lock order everywhere: tournament then obligation. Direct manager
      -- collection also locks tournament before its ledger trigger touches the
      -- outbox, so the global lane cannot deadlock it outbox->tournament.
      PERFORM 1 FROM public.tournaments t WHERE t.id=candidate.tournament_id FOR UPDATE;
      SELECT * INTO o FROM public.tournament_bounty_obligations bo
       WHERE bo.id=candidate.id AND bo.state='pending' AND bo.next_attempt_at<=now()
       FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN CONTINUE; END IF;
      -- The candidate query ran before these locks. Re-prove ordering after the
      -- tournament and exact obligation are locked so a predecessor committed
      -- in that window cannot be skipped.
      IF o.mode='pko' AND EXISTS (
        SELECT 1 FROM public.tournament_bounty_obligations prior
         WHERE prior.tournament_id=o.tournament_id AND prior.mode='pko'
           AND prior.state='pending'
           AND (prior.hand_number<o.hand_number
                OR (prior.hand_number=o.hand_number
                    AND prior.eliminated_user_id::text<o.eliminated_user_id::text))
      ) THEN
        CONTINUE;
      END IF;
      v_processed := v_processed + 1;

      -- Response-loss reconciliation before another call.
      IF o.mode <> 'mystery_chest'
         AND public.fn_bounty_obligation_has_complete_marker(o.id) THEN
        UPDATE public.tournament_bounty_obligations SET state='settled', settled_at=now(), last_error=NULL
         WHERE id=o.id;
        v_settled := v_settled + 1;
        IF NOT o.tournament_id=ANY(v_settled_tournament_ids) THEN
          v_settled_tournament_ids := array_append(v_settled_tournament_ids,o.tournament_id);
        END IF;
        CONTINUE;
      ELSIF o.mode = 'mystery_chest'
         AND public.fn_bounty_obligation_has_complete_marker(o.id) THEN
        UPDATE public.tournament_bounty_obligations SET state='settled', settled_at=now(), last_error=NULL
         WHERE id=o.id;
        v_settled := v_settled + 1;
        IF NOT o.tournament_id=ANY(v_settled_tournament_ids) THEN
          v_settled_tournament_ids := array_append(v_settled_tournament_ids,o.tournament_id);
        END IF;
        CONTINUE;
      END IF;

      IF o.mode = 'mystery_chest' THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
          'user_id', x.user_id, 'weight', x.weight,
          'is_designated_revealer', x.user_id = o.knocker_user_id
        )), '[]'::jsonb)
        INTO v_recipients
        FROM (
          SELECT (e->>'user_id')::uuid AS user_id,
                 GREATEST(COALESCE((e->>'weight')::numeric, 0), 0) AS weight
            FROM jsonb_array_elements(o.claimants) e
           WHERE NULLIF(e->>'user_id','') IS NOT NULL
        ) x;
        v_op_hex := md5('mb:' || o.id::text);
        v_op_id := (substr(v_op_hex,1,8)||'-'||substr(v_op_hex,9,4)||'-4'||substr(v_op_hex,14,3)
          ||'-8'||substr(v_op_hex,18,3)||'-'||substr(v_op_hex,21,12))::uuid;
        v_reserved := public.fn_mystery_bounty_reserve(
          o.tournament_id, o.eliminated_user_id, v_recipients, o.table_id,
          o.hand_id::text, v_op_id, 1);
        IF NOT COALESCE((v_reserved->>'ok')::boolean, false) THEN
          RAISE EXCEPTION 'reserve refused: %', COALESCE(v_reserved->>'reason','unknown');
        END IF;
        v_award_id := (v_reserved->>'award_id')::uuid;
        IF COALESCE(v_reserved->>'status','') <> 'completed' THEN
          v_result := public.fn_mystery_bounty_reveal(v_award_id, NULL, true);
          IF NOT COALESCE((v_result->>'ok')::boolean, false) THEN
            RAISE EXCEPTION 'reveal refused';
          END IF;
          v_result := public.fn_mystery_bounty_pay(v_award_id);
          IF NOT COALESCE((v_result->>'ok')::boolean, false)
             OR COALESCE((v_result->>'refused_recipients')::integer,0) > 0 THEN
            RAISE EXCEPTION 'pay refused or incomplete';
          END IF;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM public.tournament_bounty_awards a
                        WHERE a.bounty_obligation_id=o.id AND a.status='completed') THEN
          RAISE EXCEPTION 'mystery payout has no completed award marker';
        END IF;
      ELSE
        v_result := public.fn_collect_bounty_obligation(o.id);
        IF NOT COALESCE((v_result->>'ok')::boolean, false)
           AND COALESCE(v_result->>'reason','') <> 'already_collected' THEN
          RAISE EXCEPTION 'collect refused: %', COALESCE(v_result->>'reason','unknown');
        END IF;
        IF NOT public.fn_bounty_obligation_has_complete_marker(o.id) THEN
          RAISE EXCEPTION 'fixed/PKO payout markers do not conserve the full generation head';
        END IF;
      END IF;

      -- Triggers settle only after every canonical claimant (or the completed
      -- award) is durable. Never infer success from an RPC transport response.
      IF NOT EXISTS (SELECT 1 FROM public.tournament_bounty_obligations x
                      WHERE x.id=o.id AND x.state='settled') THEN
        RAISE EXCEPTION 'payout marker did not acknowledge obligation';
      END IF;
      UPDATE public.tournament_bounty_obligations
         SET last_error=NULL, attempt_count=attempt_count+1
       WHERE id=o.id;
      v_settled := v_settled + 1;
      IF NOT o.tournament_id=ANY(v_settled_tournament_ids) THEN
        v_settled_tournament_ids := array_append(v_settled_tournament_ids,o.tournament_id);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.tournament_bounty_obligations
       SET attempt_count=attempt_count+1, last_error=left(SQLERRM,1000),
             next_attempt_at=clock_timestamp()
               + make_interval(secs => LEAST(60, 5 * (attempt_count + 1)))
       WHERE id=candidate.id;
      v_failed := v_failed + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'processed', v_processed,
    'settled', v_settled, 'failed', v_failed,
    'settled_tournament_ids',to_jsonb(v_settled_tournament_ids),
    'pending', (SELECT count(*) FROM public.tournament_bounty_obligations
      WHERE state='pending' AND (p_tournament_id IS NULL OR tournament_id=p_tournament_id)),
    -- Return a DATABASE-CLOCK RELATIVE delay for the first order-eligible
    -- head. A later PKO row can have due=now while an earlier generation is
    -- backed off; using the raw minimum would spin the engine until the head
    -- became due. A host timestamp would repeat that bug under clock skew.
    'retry_after_ms',(
      SELECT CASE WHEN due_at IS NULL THEN NULL ELSE
        GREATEST(0,ceil(extract(epoch FROM (due_at-clock_timestamp()))*1000)::bigint)
      END
      FROM (
        SELECT min(bo.next_attempt_at) AS due_at
          FROM public.tournament_bounty_obligations bo
         WHERE bo.state='pending'
           AND (p_tournament_id IS NULL OR bo.tournament_id=p_tournament_id)
           AND NOT EXISTS (
             SELECT 1 FROM public.tournament_bounty_obligations prior
              WHERE prior.tournament_id=bo.tournament_id AND prior.state='pending'
                AND prior.mode='pko'
                AND (prior.hand_number<bo.hand_number
                     OR (prior.hand_number=bo.hand_number
                         AND prior.eliminated_user_id::text<bo.eliminated_user_id::text))
           )
      ) eligible_head
    ));
END;
$function$

CREATE OR REPLACE FUNCTION smarter_private.f06_prefix(t uuid, g uuid, users uuid[], ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE u uuid;
BEGIN
 PERFORM smarter_private.f06_authority(t,g);
 PERFORM public.fn_ca_lock_settlement_lane_for_tournament(t);
 PERFORM smarter_private.f06_authority(t,g,false);
 FOR u IN SELECT DISTINCT x FROM unnest(users) x ORDER BY x LOOP
 PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:'||u::text,0)); END LOOP;
 PERFORM 1 FROM public.tournaments WHERE id=t FOR UPDATE;
 PERFORM 1 FROM public.tournament_players WHERE tournament_id=t AND user_id=ANY(users) ORDER BY user_id FOR UPDATE;
 PERFORM 1 FROM public.tables WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 PERFORM s.id FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
 WHERE tb.tournament_id=t AND (s.user_id=ANY(users) OR s.table_id=ANY(ids)) ORDER BY s.id FOR UPDATE OF s;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.f06_move_guard(t uuid, u uuid, src uuid, dst uuid, chair integer, req uuid, mode text, seat uuid, occ uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE a smarter_private.f06_attempts;o smarter_private.f06_operations;m smarter_private.f06_members;g uuid;
BEGIN
 IF EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE source_table_id=dst AND state NOT IN ('acknowledged','withdrawn_before_manifest')) THEN
 RAISE EXCEPTION 'F06_DESTINATION_EXCLUDED' USING ERRCODE='55000'; END IF;
 SELECT * INTO a FROM smarter_private.f06_attempts WHERE request_id=req;
 IF NOT FOUND THEN
 IF EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE source_table_id=src AND state NOT IN ('acknowledged','withdrawn_before_manifest'))
 OR EXISTS(SELECT 1 FROM smarter_private.f06_members mm JOIN smarter_private.f06_operations oo USING(break_id) WHERE oo.tournament_id=t AND mm.user_id=u AND oo.state NOT IN ('acknowledged','withdrawn_before_manifest')
 AND NOT EXISTS(SELECT 1 FROM smarter_private.f06_attempts w WHERE w.break_id=mm.break_id AND w.user_id=mm.user_id AND w.state='winner')) THEN
 RAISE EXCEPTION 'F06_UNBOUND_MOVE' USING ERRCODE='55000'; END IF;
 RETURN; END IF;
 -- The injected pre-lane prefix already acquired lease KEY SHARE for manager.
 -- Legacy/service direct calls never acquire a late lease here; reject them.
 g:=NULLIF(current_setting('app.smarter_tournament_lease_generation',true),'')::uuid;
 PERFORM smarter_private.f06_authority(t,g,false);
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=a.break_id FOR UPDATE;
 SELECT * INTO m FROM smarter_private.f06_members WHERE break_id=a.break_id AND user_id=a.user_id;
 IF a.state<>'active' OR o.state<>'begun' OR mode<>'live_source'
 OR (o.tournament_id,a.user_id,o.source_table_id,a.destination_table_id,a.destination_seat_number,m.source_seat_id,m.occupancy_id)
 IS DISTINCT FROM (t,u,src,dst,chair,seat,occ)
 OR NOT EXISTS(SELECT 1 FROM public.tables WHERE id=src AND f06_lifecycle=o.lifecycle)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_attempts WHERE break_id=a.break_id AND user_id=u AND state='winner') THEN
 RAISE EXCEPTION 'F06_ATTEMPT_FENCED_OR_SOURCE_CHANGED' USING ERRCODE='55000'; END IF;
 INSERT INTO smarter_private.f06_dispatch VALUES(req,txid_current(),occ,seat,o.lifecycle);
END $function$

CREATE OR REPLACE FUNCTION public.fn_f06_close_break(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE o smarter_private.f06_operations;v jsonb;
BEGIN
 PERFORM smarter_private.f06_lock_break(p_tournament_id,p_lease_generation,p_break_id);
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id;
 IF o.state IN ('close_confirmed','acknowledged') THEN RETURN smarter_private.f06_state(p_break_id); END IF;
 IF o.state<>'begun' OR EXISTS(SELECT 1 FROM smarter_private.f06_attempts WHERE break_id=p_break_id AND state='active')
 OR EXISTS(SELECT 1 FROM smarter_private.f06_members m WHERE break_id=p_break_id AND NOT EXISTS(SELECT 1 FROM smarter_private.f06_attempts a WHERE a.break_id=m.break_id AND a.user_id=m.user_id AND a.state='winner')) THEN
 RETURN jsonb_build_object('ok',false,'reason','members_unresolved'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tables WHERE id=o.source_table_id AND f06_lifecycle=o.lifecycle) THEN RAISE EXCEPTION 'F06_LIFECYCLE_CHANGED' USING ERRCODE='55000'; END IF;
 v:=public.fn_close_empty_tournament_table(p_tournament_id,o.source_table_id,p_lease_generation);
 IF (v->>'ok')::boolean IS DISTINCT FROM true THEN RETURN v; END IF;
 UPDATE smarter_private.f06_operations SET state='close_confirmed',close_receipt=v WHERE break_id=p_break_id;
 RETURN smarter_private.f06_state(p_break_id);
END $function$

CREATE OR REPLACE FUNCTION smarter_private.f06_receipt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE a smarter_private.f06_attempts;d smarter_private.f06_dispatch;o smarter_private.f06_operations;m smarter_private.f06_members;
BEGIN
 SELECT * INTO a FROM smarter_private.f06_attempts WHERE request_id=NEW.request_id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 SELECT * INTO d FROM smarter_private.f06_dispatch WHERE request_id=NEW.request_id AND xid=txid_current();
 IF NOT FOUND THEN RAISE EXCEPTION 'F06_RECEIPT_WITHOUT_DISPATCH' USING ERRCODE='55000'; END IF;
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=a.break_id;
 SELECT * INTO m FROM smarter_private.f06_members WHERE break_id=a.break_id AND user_id=a.user_id;
 IF a.state<>'active' OR (NEW.tournament_id,NEW.user_id,NEW.source_table_id,NEW.destination_table_id,NEW.source_seat_id,NEW.source_seat_number,NEW.destination_seat_number,NEW.source_mode)
 IS DISTINCT FROM (o.tournament_id,a.user_id,o.source_table_id,a.destination_table_id,m.source_seat_id,m.source_seat_number,a.destination_seat_number,'live_source'::text) THEN
 RAISE EXCEPTION 'F06_RECEIPT_CONFLICT' USING ERRCODE='55000'; END IF;
 UPDATE smarter_private.f06_attempts SET state='winner',receipt=to_jsonb(NEW)||jsonb_build_object('source_occupancy_id',d.occupancy_id,'source_lifecycle',d.lifecycle::text,'break_id',a.break_id)
 WHERE request_id=NEW.request_id;
 DELETE FROM smarter_private.f06_dispatch WHERE request_id=NEW.request_id;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_close_empty_tournament_table(p_tournament_id uuid, p_table_id uuid, p_lease_generation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor text;
  v_actor_tournament_id uuid;
  v_actor_generation uuid;
  v_parent_status text;
  v_table_status text;
  v_current_players integer;
BEGIN
  IF p_tournament_id IS NULL OR p_table_id IS NULL OR p_lease_generation IS NULL THEN
    RAISE EXCEPTION 'fn_close_empty_tournament_table requires three UUIDs'
      USING ERRCODE = '22023';
  END IF;

  v_actor := current_setting('app.smarter_data_actor', true);
  BEGIN
    v_actor_tournament_id :=
      NULLIF(current_setting('app.smarter_tournament_id', true), '')::uuid;
    v_actor_generation :=
      NULLIF(current_setting('app.smarter_tournament_lease_generation', true), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'TOURNAMENT_MANAGER_FENCED: malformed request authority'
      USING ERRCODE = '42501';
  END;

  IF v_actor IS DISTINCT FROM 'tournament-manager'
     OR v_actor_tournament_id IS DISTINCT FROM p_tournament_id
     OR v_actor_generation IS DISTINCT FROM p_lease_generation THEN
    RAISE EXCEPTION 'TOURNAMENT_MANAGER_FENCED: table close authority does not match request'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id
     AND l.protocol_version = 2
     AND l.lease_generation = p_lease_generation
     AND l.heartbeat_at >= clock_timestamp() - interval '30 seconds'
   -- A HAND COMMIT DOES NOT HOLD THE LEASE AGAINST ITS OWN HEARTBEAT (2026-09-10)
   FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TOURNAMENT_MANAGER_FENCED: table close lease is stale'
      USING ERRCODE = '42501';
  END IF;

  SELECT upper(t.status::text)
    INTO v_parent_status
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND OR v_parent_status <> 'RUNNING' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'tournament_not_running',
      'status', v_parent_status
    );
  END IF;

  SELECT lower(t.status::text), COALESCE(t.current_players, 0)
    INTO v_table_status, v_current_players
    FROM public.tables t
   WHERE t.id = p_table_id
     AND t.tournament_id = p_tournament_id
     AND NOT COALESCE(t.is_deleted, false)
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;

  PERFORM 1
    FROM public.table_seats s
   WHERE s.table_id = p_table_id
     AND s.left_at IS NULL
   ORDER BY s.id
   FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'live_seats_remain');
  END IF;

  IF v_table_status <> 'closed' OR v_current_players <> 0 THEN
    UPDATE public.tables
       SET status = 'closed',
           current_players = 0,
           updated_at = clock_timestamp()
     WHERE id = p_table_id
       AND tournament_id = p_tournament_id;
  END IF;

  SELECT lower(t.status::text), COALESCE(t.current_players, 0)
    INTO v_table_status, v_current_players
    FROM public.tables t
   WHERE t.id = p_table_id
     AND t.tournament_id = p_tournament_id;

  RETURN jsonb_build_object(
    'ok', v_table_status = 'closed' AND v_current_players = 0,
    'reason', CASE
      WHEN v_table_status = 'closed' AND v_current_players = 0 THEN 'closed'
      ELSE 'close_not_durable'
    END,
    'table_id', p_table_id,
    'tournament_id', p_tournament_id,
    'status', v_table_status,
    'current_players', v_current_players
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_request_tournament_abort(p_operation_id uuid, p_tournament_ids uuid[], p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE ids uuid[]; t public.tournaments; generation uuid; prior smarter_private.tournament_abort_operations;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'operator_abort_service_required' USING ERRCODE='42501';END IF;
 IF p_operation_id IS NULL OR p_tournament_ids IS NULL OR cardinality(p_tournament_ids) NOT BETWEEN 1 AND 1000
 OR array_position(p_tournament_ids,NULL) IS NOT NULL OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 10 AND 500 THEN
  RAISE EXCEPTION 'operator_abort_identity_invalid' USING ERRCODE='22023';END IF;
 SELECT array_agg(id ORDER BY id) INTO ids FROM (SELECT DISTINCT unnest(p_tournament_ids) id)x;
 IF cardinality(ids)<>cardinality(p_tournament_ids) THEN RAISE EXCEPTION 'operator_abort_duplicate_target' USING ERRCODE='22023';END IF;
 PERFORM smarter_private.bulk_closure_admission('request_abort',ids);
 PERFORM smarter_private.assert_tournament_abort_not_recovered(p_operation_id,id) FROM unnest(ids) AS requested(id);
 IF NOT pg_try_advisory_xact_lock(hashtextextended('ca:tournament-abort:'||p_operation_id::text,0)) THEN
  RAISE EXCEPTION 'OPERATOR_ABORT_BUSY' USING ERRCODE='55P03';END IF;
 SELECT * INTO prior FROM smarter_private.tournament_abort_operations WHERE operation_id=p_operation_id;
 IF FOUND THEN
  IF prior.tournament_ids IS DISTINCT FROM ids OR prior.reason IS DISTINCT FROM btrim(p_reason) THEN
   RAISE EXCEPTION 'operator_abort_operation_reused' USING ERRCODE='22023';END IF;
  RETURN jsonb_build_object('ok',true,'operation_id',p_operation_id,'tournament_ids',ids,'stop_requested',true,'replayed',true);
 END IF;
 -- This existing try-admission takes G and the settlement barrier before any
 -- parent/child row. It never queues an exclusive global request behind play.
 PERFORM smarter_private.cancellation_lane(ids[1]);
 PERFORM 1 FROM public.tournaments WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 IF (SELECT count(*) FROM public.tournaments WHERE id=ANY(ids))<>cardinality(ids) THEN
  RAISE EXCEPTION 'operator_abort_target_missing' USING ERRCODE='P0002';END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.tournament_abort_targets WHERE tournament_id=ANY(ids)) THEN
  RAISE EXCEPTION 'operator_abort_target_owned' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM public.tournaments WHERE id=ANY(ids) AND (started_at IS NULL OR upper(status) NOT IN('RUNNING','BREAK','LATE_REG'))) THEN
  RAISE EXCEPTION 'operator_abort_requires_started_unsettled_event' USING ERRCODE='55000';END IF;
 INSERT INTO smarter_private.tournament_abort_operations(operation_id,tournament_ids,reason,cohort_hash)
 VALUES(p_operation_id,ids,btrim(p_reason),md5(ids::text));
 FOR t IN SELECT * FROM public.tournaments WHERE id=ANY(ids) ORDER BY id LOOP
  SELECT lease_generation INTO generation FROM public.engine_tournament_leases WHERE tournament_id=t.id AND protocol_version=2 FOR KEY SHARE;
  IF generation IS NULL THEN RAISE EXCEPTION 'operator_abort_manager_identity_missing:%',t.id USING ERRCODE='55000';END IF;
  INSERT INTO smarter_private.tournament_abort_targets(operation_id,tournament_id,state,asset,requested_generation)
  VALUES(p_operation_id,t.id,'stop_requested',CASE WHEN public.fn_poker_diamond_tournament(t.id) THEN 'diamonds' ELSE 'chips' END,generation);
  INSERT INTO smarter_private.tournament_abort_boundaries(operation_id,tournament_id,table_id,lifecycle,required,request_generation,existing_permits)
  SELECT p_operation_id,t.id,tb.id,tb.f06_lifecycle,lower(tb.status)<>'closed' AND NOT coalesce(tb.is_deleted,false),generation,
   coalesce((SELECT jsonb_agg(to_jsonb(h) ORDER BY h.permit_id) FROM smarter_private.f06_hand_permits h WHERE h.table_id=tb.id AND h.state='reserved'),'[]'::jsonb)
  FROM public.tables tb WHERE tb.tournament_id=t.id ORDER BY tb.id;
 END LOOP;
 RETURN jsonb_build_object('ok',true,'operation_id',p_operation_id,'tournament_ids',ids,'stop_requested',true,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.fn_collect_bounty(p_tournament_id uuid, p_eliminated_user_id uuid, p_collector_user_id uuid, p_claimants jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  o public.tournament_bounty_obligations%ROWTYPE;
  v_result jsonb;
  v_shares jsonb;
  v_paid_cash numeric;
  v_added_to_head numeric;
  v_context text := current_setting('app.bounty_obligation_id',true);
  v_prior_context text;
  v_obligation_count integer;
  v_pko_watermark bigint;
  v_predecessors jsonb;
  v_t record;
  v_elim record;
  v_head numeric;
  v_available numeric;
  v_payable numeric;
  v_cash numeric;
  v_to_head numeric;
  v_cents integer;
  v_cash_cents integer;
  v_mode text;
  v_funded boolean;
  v_claimants jsonb;
  v_n integer;
  v_total_weight numeric;
  v_paid_total numeric := 0;
  v_head_total numeric := 0;
  c record;
  v_share_cents integer;
  v_assigned_cents integer := 0;
  v_i integer := 0;
  v_prior numeric;
  v_settle jsonb;
  v_desc text;
  v_core_collector_user_id uuid;
  v_core_claimants jsonb;
BEGIN
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM 1 FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','tournament_not_found'); END IF;

  IF COALESCE(v_context,'')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    SELECT * INTO o FROM public.tournament_bounty_obligations bo
     WHERE bo.id=v_context::uuid AND bo.tournament_id=p_tournament_id
       AND bo.eliminated_user_id=p_eliminated_user_id
       AND bo.mode<>'mystery_chest'
     FOR UPDATE;
  ELSE
    SELECT count(*) INTO v_obligation_count
      FROM public.tournament_bounty_obligations bo
     WHERE bo.tournament_id=p_tournament_id
       AND bo.eliminated_user_id=p_eliminated_user_id
       AND bo.mode<>'mystery_chest';
    IF v_obligation_count>1 THEN
      RETURN jsonb_build_object('ok',false,'reason','bounty_generation_identity_required');
    END IF;
    SELECT * INTO o FROM public.tournament_bounty_obligations bo
     WHERE bo.tournament_id=p_tournament_id
       AND bo.eliminated_user_id=p_eliminated_user_id
       AND bo.mode<>'mystery_chest'
     FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','bounty_obligation_not_ready');
  END IF;
  IF o.state='settled' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'user_id',b.collector_player_id,
             'cash',GREATEST(0,b.bounty_amount-COALESCE(b.added_to_collector_bounty,0)),
             'to_head',COALESCE(b.added_to_collector_bounty,0))
             ORDER BY b.collector_player_id),'[]'::jsonb),
           COALESCE(sum(GREATEST(0,b.bounty_amount-COALESCE(b.added_to_collector_bounty,0))),0),
           COALESCE(sum(b.added_to_collector_bounty),0)
      INTO v_shares,v_paid_cash,v_added_to_head
      FROM public.tournament_bounties b
     WHERE b.bounty_obligation_id=o.id;
    IF NOT public.fn_bounty_obligation_has_complete_marker(o.id) THEN
      RETURN jsonb_build_object('ok',false,'reason','settled_marker_incomplete',
                                'obligation_id',o.id);
    END IF;
    IF o.mode='pko' THEN
      INSERT INTO public.tournament_pko_settlement_watermarks
        (tournament_id,last_settled_hand_number,last_obligation_id)
      VALUES (o.tournament_id,o.hand_number,o.id)
      ON CONFLICT (tournament_id) DO UPDATE
        SET last_settled_hand_number=GREATEST(
              public.tournament_pko_settlement_watermarks.last_settled_hand_number,
              EXCLUDED.last_settled_hand_number),
            last_obligation_id=CASE
              WHEN EXCLUDED.last_settled_hand_number>=
                   public.tournament_pko_settlement_watermarks.last_settled_hand_number
              THEN EXCLUDED.last_obligation_id
              ELSE public.tournament_pko_settlement_watermarks.last_obligation_id END,
            updated_at=now();
    END IF;
    RETURN jsonb_build_object('ok',true,'already',true,'obligation_id',o.id,
      'marker_verified',true,'mode',o.mode,'head',o.head_amount,
      'paid_cash',v_paid_cash,'added_to_head',v_added_to_head,
      'split',jsonb_array_length(v_shares)>1,'shares',v_shares);
  END IF;

  IF o.mode='pko' THEN
    v_predecessors:=public.fn_pko_claim_predecessor_status_v1(
      o.tournament_id,o.eliminated_user_id,o.table_id,o.hand_id,
      o.hand_number,o.seat_joined_at);
    IF v_predecessors->>'ok' IS DISTINCT FROM 'true' THEN
      RETURN jsonb_build_object('ok',false,'reason','pko_predecessor_not_ready',
                               'predecessor_proof',v_predecessors);
    END IF;
  END IF;

  IF o.mode='pko' THEN
    SELECT w.last_settled_hand_number INTO v_pko_watermark
      FROM public.tournament_pko_settlement_watermarks w
     WHERE w.tournament_id=o.tournament_id FOR UPDATE;
    IF v_pko_watermark IS NOT NULL AND o.hand_number<v_pko_watermark THEN
      v_predecessors:=public.fn_pko_watermark_admission_status_v1(
        o.tournament_id,o.eliminated_user_id,o.table_id,o.hand_id,
        o.hand_number,o.seat_joined_at,o.claimants);
      IF v_predecessors->>'ok' IS DISTINCT FROM 'true' THEN
        RETURN jsonb_build_object('ok',false,'reason','pko_order_unproven',
          'watermark_proof',v_predecessors);
      END IF;
    END IF;
    -- The accepted-candidate guard above proves every actual incoming head
    -- dependency, including larger reserved hand numbers. Unrelated pending
    -- heads do not change this captured head and must not serialize its payout.
  END IF;

  -- Ignore caller ordering/weights. The exact pot-derived, roster-validated
  -- snapshot stored by the atomic claim is the only payout authority. The
  -- audited payer is inlined here so this root survives retirement of the
  -- temporary rolling-deployment body.
  v_core_collector_user_id := o.knocker_user_id;
  v_core_claimants := o.claimants;
  v_prior_context := current_setting('app.bounty_obligation_id',true);
  PERFORM set_config('app.bounty_obligation_id',o.id::text,true);

  <<collect_core>>
  BEGIN
    IF v_core_collector_user_id IS NULL OR p_eliminated_user_id IS NULL THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'missing_party');
      EXIT collect_core;
    END IF;

    SELECT id, is_bounty, is_pko, is_mystery_bounty, bounty_amount,
           bounty_pool, bounty_pool_paid, mystery_bounty_stage
      INTO v_t FROM tournaments WHERE id = p_tournament_id FOR UPDATE;
    IF NOT FOUND THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
      EXIT collect_core;
    END IF;
    IF NOT (COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
            OR COALESCE(v_t.is_mystery_bounty,false)) THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'not_a_bounty_tournament');
      EXIT collect_core;
    END IF;

    IF COALESCE(v_t.is_pko, false) AND COALESCE(v_t.is_mystery_bounty, false) THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'undefined_pko_mystery_hybrid',
        'detail', 'PKO heads claim against bounty_pool; mystery chests are a sealed '
               || 'inventory. No split satisfies both. This event should not exist.');
      EXIT collect_core;
    END IF;

    /* A BUST BELONGS TO THE PHASE ITS HAND WAS PLAYED IN (2026-09-11). A
       persisted mystery_pre obligation is a head earned before activation;
       the seed keeps it outside the chest pool, so it is paid from the
       regular half after the chests open. Refusing it only strands it. */
    IF COALESCE(v_t.is_mystery_bounty, false)
       AND v_t.mystery_bounty_stage = 'active'
       AND o.mode IS DISTINCT FROM 'mystery_pre' THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'mystery_phase_active');
      EXIT collect_core;
    END IF;

    IF EXISTS (
      SELECT 1 FROM tournament_bounties b
       WHERE b.tournament_id = p_tournament_id
         AND b.eliminated_player_id = p_eliminated_user_id
         AND (
           b.bounty_obligation_id = (SELECT pending.id
             FROM tournament_bounty_obligations pending
            WHERE pending.tournament_id=p_tournament_id
              AND pending.eliminated_user_id=p_eliminated_user_id
              AND pending.mode <> 'mystery_chest' AND pending.state='pending'
            ORDER BY pending.hand_number, pending.created_at LIMIT 1)
           OR (b.bounty_obligation_id IS NULL AND NOT EXISTS (
             SELECT 1 FROM tournament_bounty_obligations pending
              WHERE pending.tournament_id=p_tournament_id
                AND pending.eliminated_user_id=p_eliminated_user_id
                AND pending.mode <> 'mystery_chest' AND pending.state='pending'))
         )
    ) THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'already_collected');
      EXIT collect_core;
    END IF;

    SELECT current_bounty INTO v_elim
      FROM tournament_players
     WHERE tournament_id = p_tournament_id AND user_id = p_eliminated_user_id
     FOR UPDATE;
    IF NOT FOUND THEN
      v_result := jsonb_build_object(
        'ok', false, 'reason', 'eliminated_player_not_in_tournament');
      EXIT collect_core;
    END IF;

    v_mode := CASE WHEN COALESCE(v_t.is_pko,false) THEN 'pko'
                   WHEN COALESCE(v_t.is_mystery_bounty,false) THEN 'mystery_pre'
                   ELSE 'regular' END;

    v_head := COALESCE(NULLIF(v_elim.current_bounty, 0), v_t.bounty_amount, 0);
    IF v_head <= 0 THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'no_head_value');
      EXIT collect_core;
    END IF;
    IF EXISTS (
      SELECT 1 FROM tournament_bounty_obligations pending
       WHERE pending.tournament_id=p_tournament_id
         AND pending.eliminated_user_id=p_eliminated_user_id
         AND pending.mode <> 'mystery_chest' AND pending.state='pending'
         AND pending.head_amount IS DISTINCT FROM round(v_head,2)
    ) THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'head_snapshot_changed');
      EXIT collect_core;
    END IF;

    v_funded := COALESCE(v_t.bounty_pool, 0) > 0;
    SELECT round(COALESCE(v_t.bounty_pool,0) - COALESCE(SUM(
             CASE WHEN lower(wt.type) = 'debit' THEN -abs(wt.amount)
                  ELSE wt.amount END), 0), 2)
      INTO v_available
      FROM wallet_transactions wt
     WHERE wt.related_entity_id = p_tournament_id
       AND wt.category = 'bounty';
    -- DIAMOND PHASE 9: a Diamond bounty is a ledger row, not a wallet row;
    -- the bank is what the entries put in less what it already paid.
    IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
      SELECT e.bounty_balance INTO v_available
        FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id) e;
    END IF;

    IF v_funded THEN
      IF v_available <= 0 THEN
        v_result := jsonb_build_object('ok', false, 'reason', 'bounty_pool_exhausted',
                                      'head', v_head, 'available', v_available);
        EXIT collect_core;
      END IF;
      IF v_available < v_head THEN
        v_result := jsonb_build_object('ok', false, 'reason', 'bounty_pool_underfunded',
                                      'head', v_head, 'available', v_available);
        EXIT collect_core;
      END IF;
      v_payable := v_head;
    ELSE
      v_payable := v_head;
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'user_id', x.uid, 'weight', x.w)), '[]'::jsonb)
      INTO v_claimants
      FROM (
        SELECT (e->>'user_id')::uuid AS uid, (e->>'weight')::numeric AS w
          FROM jsonb_array_elements(COALESCE(v_core_claimants, '[]'::jsonb)) e
         WHERE (e->>'user_id') IS NOT NULL
           AND COALESCE((e->>'weight')::numeric, 0) > 0
           AND EXISTS (
             SELECT 1 FROM tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.user_id = (e->>'user_id')::uuid)
      ) x;
    v_n := jsonb_array_length(v_claimants);
    IF v_n <= 1 THEN
      v_claimants := jsonb_build_array(jsonb_build_object(
        'user_id', v_core_collector_user_id, 'weight', 1));
      v_n := 1;
    END IF;
    SELECT sum((e->>'weight')::numeric) INTO v_total_weight
      FROM jsonb_array_elements(v_claimants) e;

    v_cents := round(v_payable * 100)::integer;
    v_desc := CASE v_mode
      WHEN 'pko' THEN 'PKO bounty (cash half) from eliminated player'
      WHEN 'mystery_pre' THEN 'Bounty collected before the mystery phase opened'
      ELSE 'Bounty collected from eliminated player' END
      || CASE WHEN v_n > 1 THEN ' (split pot, ' || v_n || ' winners)' ELSE '' END;
    v_shares := '[]'::jsonb;

    FOR c IN
      SELECT (e->>'user_id')::uuid AS uid, (e->>'weight')::numeric AS w
        FROM jsonb_array_elements(v_claimants) e
       ORDER BY (e->>'weight')::numeric ASC, (e->>'user_id')
    LOOP
      v_i := v_i + 1;
      IF v_i < v_n THEN
        v_share_cents := floor(v_cents * c.w / v_total_weight)::integer;
        IF v_share_cents > 0 THEN
          v_share_cents := public.fn_ca_unit_floor_cents(
            v_share_cents::bigint,
            public.fn_ca_tournament_unit_cents(p_tournament_id))::integer;
        END IF;
      ELSE
        v_share_cents := v_cents - v_assigned_cents;
      END IF;
      v_assigned_cents := v_assigned_cents + v_share_cents;
      CONTINUE WHEN v_share_cents <= 0;

      IF v_mode = 'pko' THEN
        v_cash_cents := public.fn_ca_unit_floor_cents(
          (v_share_cents / 2)::bigint,
          public.fn_ca_tournament_unit_cents(p_tournament_id))::integer;
        v_cash := v_cash_cents / 100.0;
        v_to_head := (v_share_cents - v_cash_cents) / 100.0;
      ELSE
        v_cash := v_share_cents / 100.0;
        v_to_head := 0;
      END IF;

      PERFORM public.fn_ca_promo_profit_add_earned_head(p_tournament_id,c.uid,v_to_head);
      IF v_cash > 0 THEN
        v_prior := COALESCE((
          SELECT debt.amount_paid FROM public.tournament_obligations debt
           WHERE debt.tournament_id = p_tournament_id
             AND debt.kind = 'bounty'
             AND debt.place IS NULL
             AND debt.user_id = c.uid), 0);
        v_settle := public.fn_settle_tournament_obligation(
          p_tournament_id, 'bounty', NULL, c.uid, round(v_prior + v_cash, 2),
          'fn_collect_bounty', v_desc);
        IF NOT COALESCE((v_settle->>'ok')::boolean, false) THEN
          RAISE EXCEPTION
            'fn_collect_bounty: bounty of % to % in tournament % refused (%); nothing recorded',
            v_cash, c.uid, p_tournament_id,
            COALESCE(v_settle->>'refused_reason', 'unknown');
        END IF;
        IF round(COALESCE((v_settle->>'paid')::numeric, 0), 2)
             <> round(v_cash, 2) THEN
          RAISE EXCEPTION
            'fn_collect_bounty: obligation paid % but the share is % for % in tournament %; nothing recorded',
            v_settle->>'paid', v_cash, c.uid, p_tournament_id;
        END IF;
      END IF;

      UPDATE tournament_players
         SET bounties_collected = COALESCE(bounties_collected,0) + 1,
             bounty_winnings = round(COALESCE(bounty_winnings,0) + v_cash, 2),
             current_bounty = round(COALESCE(current_bounty,0) + v_to_head, 2)
       WHERE tournament_id = p_tournament_id AND user_id = c.uid;

      INSERT INTO tournament_bounties
        (tournament_id, eliminated_player_id, collector_player_id, bounty_amount,
         added_to_collector_bounty, is_mystery_revealed)
      VALUES
        (p_tournament_id, p_eliminated_user_id, c.uid,
         round(v_share_cents / 100.0, 2),
         CASE WHEN v_to_head > 0 THEN v_to_head ELSE NULL END, false);

      v_paid_total := v_paid_total + v_cash;
      v_head_total := v_head_total + v_to_head;
      v_shares := v_shares || jsonb_build_object(
        'user_id', c.uid, 'cash', v_cash, 'to_head', v_to_head);
    END LOOP;

    PERFORM public.fn_ca_promo_profit_retire_knocked_out_head(p_tournament_id,p_eliminated_user_id,v_head);
    UPDATE tournament_players SET current_bounty = 0
     WHERE tournament_id = p_tournament_id AND user_id = p_eliminated_user_id;

    IF v_funded THEN
      UPDATE tournaments
         SET bounty_pool_paid = round(COALESCE(bounty_pool_paid,0) + v_paid_total, 2)
       WHERE id = p_tournament_id;
    END IF;

    v_result := jsonb_build_object(
      'ok', true, 'mode', v_mode, 'funded', v_funded,
      'head', v_head, 'paid_cash', round(v_paid_total, 2),
      'added_to_head', round(v_head_total, 2),
      'split', v_n > 1, 'shares', v_shares,
      'capped', v_funded AND v_payable < v_head,
      'pool_remaining', CASE WHEN v_funded
                             THEN round(v_available - v_paid_total, 2) END);
  END collect_core;

  PERFORM set_config('app.bounty_obligation_id',COALESCE(v_prior_context,''),true);

  IF NOT COALESCE((v_result->>'ok')::boolean,false) THEN
    -- A semantic pre-write refusal is safe to commit and stays pending. Any
    -- accepted payer result below must satisfy the exact marker postcondition
    -- or raise so its wallet/head/counter mutations roll back atomically.
    RETURN v_result || jsonb_build_object('obligation_id',o.id);
  END IF;

  UPDATE public.tournament_bounty_obligations bo
     SET state='settled',settled_at=COALESCE(settled_at,now()),last_error=NULL
   WHERE bo.id=o.id AND bo.state='pending'
     AND public.fn_bounty_obligation_has_complete_marker(bo.id);
  IF NOT public.fn_bounty_obligation_has_complete_marker(o.id)
     OR NOT EXISTS (SELECT 1 FROM public.tournament_bounty_obligations bo
                     WHERE bo.id=o.id AND bo.state='settled') THEN
    RAISE EXCEPTION 'accepted bounty payout did not produce the exact settled marker for %',o.id
      USING ERRCODE='check_violation';
  END IF;
  IF o.mode='pko' THEN
    INSERT INTO public.tournament_pko_settlement_watermarks
      (tournament_id,last_settled_hand_number,last_obligation_id)
    VALUES (o.tournament_id,o.hand_number,o.id)
    ON CONFLICT (tournament_id) DO UPDATE
      SET last_settled_hand_number=GREATEST(
            public.tournament_pko_settlement_watermarks.last_settled_hand_number,
            EXCLUDED.last_settled_hand_number),
          last_obligation_id=CASE
            WHEN EXCLUDED.last_settled_hand_number>=
                 public.tournament_pko_settlement_watermarks.last_settled_hand_number
            THEN EXCLUDED.last_obligation_id
            ELSE public.tournament_pko_settlement_watermarks.last_obligation_id END,
          updated_at=now();
  END IF;
  RETURN v_result || jsonb_build_object('obligation_id',o.id,'marker_verified',true);
END;
$function$

CREATE OR REPLACE FUNCTION smarter_private.cancellation_lane(p_tournament_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE
 g bigint := hashtextextended('ca:tournament-terminal-settlement:v1',0);
 f bigint := hashtextextended('ca:tournament-finish-lane:v1',0);
 b bigint := hashtextextended('ca:hand-settlement-barrier:v1',0);
 held text := COALESCE(current_setting('ca.finish_lane_tournament',true),'');
 scope text := COALESCE(current_setting('ca.finish_lane_scope',true),'');
 gx boolean; bx boolean; gs boolean; fx boolean; prior_t boolean;
BEGIN
 IF p_tournament_id IS NULL THEN
  RAISE EXCEPTION 'Tournament id is required' USING ERRCODE='22004';
 END IF;
 SELECT COALESCE(bool_or(k.key=g AND l.mode='ExclusiveLock'),false),
        COALESCE(bool_or(k.key=b AND l.mode='ExclusiveLock'),false),
        COALESCE(bool_or(k.key=g AND l.mode IN('ShareLock','ExclusiveLock')),false),
        COALESCE(bool_or(k.key=f AND l.mode='ExclusiveLock'),false)
 INTO gx,bx,gs,fx
 FROM pg_catalog.pg_locks l JOIN (VALUES(g),(b),(f)) k(key)
 ON l.classid=((k.key>>32)&4294967295)::oid AND l.objid=(k.key&4294967295)::oid
 WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.objsubid=1
 AND l.database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database()) AND l.granted;
 -- A batch already holding the original G/B barrier keeps that authority.
 -- Do not manufacture a single-event marker for its multiple-event work.
 IF gx THEN
  IF NOT bx THEN RAISE EXCEPTION 'CANCELLATION_GLOBAL_AUTHORITY_INCOMPLETE' USING ERRCODE='55000'; END IF;
  RETURN;
 END IF;
 -- 20261118171613: inside a club lane (fn_ca_lock_settlement_lane_for_club:
 -- G shared, F shared, the club's bank scope and C(club) exclusive, every live
 -- event of the club exclusive) a cancellation of one of that club's events
 -- (the welcome unwind cancels its unused games) has its whole authority:
 -- the event's T is held or taken here without waiting.
 IF COALESCE(current_setting('ca.club_lane',true),'')<>'' AND held='' AND scope='' THEN
  IF NOT gs OR NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.id=p_tournament_id
       AND t.club_id::text=current_setting('ca.club_lane',true))
     OR NOT pg_try_advisory_xact_lock(hashtextextended('ca:tournament-terminal-settlement:v1:'||p_tournament_id::text,0)) THEN
   RAISE EXCEPTION 'CANCELLATION_CLUB_AUTHORITY_INCOMPLETE' USING ERRCODE='55000';
  END IF;
  RETURN;
 END IF;
 -- A marker alone is never authority. Validate its existing global/event
 -- identity, reject bank scope, and require the already-held finish barrier.
 -- Only this existing sweep authority may retain its original shared G lane.
 IF held<>'' OR scope<>'' THEN
  IF NOT gs OR NOT fx OR scope<>'' THEN
   RAISE EXCEPTION 'CANCELLATION_FINISH_AUTHORITY_INCOMPLETE' USING ERRCODE='55000';
  END IF;
  SELECT EXISTS(SELECT 1 FROM pg_catalog.pg_locks l
   WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.objsubid=1
   AND l.database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended('ca:tournament-terminal-settlement:v1:'||held,0)>>32)&4294967295)::oid
   AND l.objid=(hashtextextended('ca:tournament-terminal-settlement:v1:'||held,0)&4294967295)::oid
   AND l.mode='ExclusiveLock' AND l.granted) INTO prior_t;
  IF held<>p_tournament_id::text OR NOT prior_t THEN
   RAISE EXCEPTION 'CANCELLATION_EVENT_AUTHORITY_INCOMPLETE' USING ERRCODE='55000';
  END IF;
  RETURN;
 END IF;
 -- Preserve the original complete financial exclusion. A try-lock never
 -- queues an exclusive global request ahead of subsequent hand readers.
 -- Busy callers receive an authoritative refusal before cancellation writes.
 IF NOT pg_try_advisory_xact_lock(g) THEN
  RAISE EXCEPTION 'CANCELLATION_GLOBAL_LANE_BUSY' USING ERRCODE='55P03';
 END IF;
 IF NOT pg_try_advisory_xact_lock(b) THEN
  RAISE EXCEPTION 'CANCELLATION_BARRIER_BUSY' USING ERRCODE='55P03';
 END IF;
 -- Do not change existing finish scope or manufacture event authority.
 -- Raising above rolls back this admission's partial locks with its caller.
END;
$function$
